// This CSD strategy alternates between unconstrained and constrained phases to generate free-form reasoning text followed by arithmetic expressions. In the unconstrained phase, the model generates general reasoning text without grammar constraints. When the phrase "<<"" is detected, the model transitions to the constrained phase, where it generates arithmetic expressions within the delimiters. To prevent premature closure of expressions, logit manipulation is used to penalize the token ">" when the expression length is less than 5 tokens. Additionally, confidence gating is applied to ensure that the model's top choice is consistent with the grammar rules before applying constraints.
// CSD_RATIONALE_END

generated := [];
var steps := 0;
var insideConstrained := false;
var currentConstrained: Prefix := [];
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  invariant helpers.cost == steps
  decreases maxSteps - steps
{
  if !insideConstrained {
    // UNCONSTRAINED PHASE: generate general reasoning text
    lm.GenerateLogits(prompt + generated);

    // Optionally penalize << to force longer reasoning in the beginning
    if steps < 15 {
      helpers.PenalizeTokenLogits(lm, ["<<"], 8.0);
    }

    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;

    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;

    // Transition to constrained mode if << is detected
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
