    // CONSTRAINED PHASE: generate arithmetic expressions within << >>
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 3);
    if narrow || parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // Confidence-gated step to ensure alignment with grammar rules
      var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
