      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    // CONSTRAINED PHASE: generate arithmetic expressions within << >>
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 3);
    if narrow || parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // Confidence-gated step to ensure alignment with grammar rules
      var next, wasConstrained := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
      if wasConstrained {
        if ">>" in lm.Tokens {  // Guard to avoid logit manipulation errors
          helpers.PenalizeTokenLogits(lm, [">>"], 3.0);  // Penalize >> if expression is too short
        }
      }

      helpers.BoostTokenLogits(lm, parser.ValidNextTokens(currentConstrained), 5.0);
      helpers.cost := helpers.cost + 1;
      generated := generated + [next];
      steps := steps + 1;

      if parser.IsValidPrefix(currentConstrained + [next]) {
        currentConstrained := currentConstrained + [next];
        if Contains(next, ">>") { insideConstrained := false; }
      } else {
        // If the next token does not align with the grammar, abandon the constrained mode
        insideConstrained := false;
      }
    }
  }
}

cost := helpers.cost;
